using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;

namespace Jarvis.Windows.Core;

/** User-authenticated, time-limited relay through their Cloudflare Worker.
 * Requests are NEVER generated by AI. Only the user's own spoken/typed
 * commands are eligible. Worker token is protected by Windows DPAPI.
 * Pixel is finance authority and Watch7 is reached via companion Pixel.
 */
public sealed class DeviceRelayClient : IDisposable {
    private readonly HttpClient _http=new() {Timeout=TimeSpan.FromSeconds(12)};
    private readonly StateStore _store;
    private readonly JarvisSettings _settings;
    private readonly HashSet<Guid> _completed=new();
    public event Func<RemoteCommand,Task<RemoteResult>>? CommandReceived;
    public event Action<string>? Status;

    public sealed record RemoteCommand(Guid Id,string Origin,string Target,string Command);
    public sealed record RemoteResult(bool Ok,string Detail);
    public DeviceRelayClient(StateStore store,JarvisSettings settings) {
        _store=store;_settings=settings;
    }
    private (Uri Url,string Token) Credentials() {
        var endpoint=_settings.WorkerUrl;
        if(!AiClient.ValidEndpoint(endpoint))
            throw new InvalidOperationException("Для зв'язку пристроїв потрібен Cloudflare HTTPS /chat.");
        var token=_store.ReadWorkerToken();
        if(string.IsNullOrWhiteSpace(token) || token.Length<20)
            throw new InvalidOperationException("Немає захищеного коду Worker.");
        return (new Uri(new Uri(endpoint).GetLeftPart(UriPartial.Authority)),token);
    }
    private HttpRequestMessage Request(HttpMethod method,string path,string token,object? data=null) {
        var r=new HttpRequestMessage(method,path);
        r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);
        if(data!=null)r.Content=new StringContent(JsonSerializer.Serialize(data),
            Encoding.UTF8,"application/json");
        return r;
    }
    private async Task<JsonDocument> SendAsync(HttpRequestMessage request,
        CancellationToken cancel) {
        using(request)
        using(var response=await _http.SendAsync(request,cancel)) {
            if(response.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden)
                throw new InvalidOperationException("Перевір секрет Worker для зв'язку пристроїв.");
            if(response.StatusCode==HttpStatusCode.ServiceUnavailable)
                throw new InvalidOperationException("Cloudflare Relay ще не розгорнуто або недоступний.");
            if(!response.IsSuccessStatusCode)
                throw new InvalidOperationException("Команда не доставлена: HTTP "+(int)response.StatusCode);
            await using var stream=await response.Content.ReadAsStreamAsync(cancel);
            return await JsonDocument.ParseAsync(stream,cancellationToken:cancel);
        }
    }
    public async Task<bool> IsOnlineAsync(JarvisDevice device,CancellationToken cancel) {
        var (url,token)=Credentials();
        using var json=await SendAsync(Request(HttpMethod.Get,
            new Uri(url,$"/device/v1/online?device={DeviceRouting.WireId(device)}").ToString(),
            token),cancel);
        return json.RootElement.TryGetProperty("online",out var value)&&value.GetBoolean();
    }

    public async Task<RemoteResult> SendCommandAsync(JarvisDevice origin,
        JarvisDevice target,string utterance,CancellationToken cancellation) {
        if(utterance.Length is <1 or >250 ||
           utterance.Any(char.IsControl))
            throw new ArgumentException("Дистанційна команда: 1–250 символів без керувальних знаків.");
        if(origin==target)throw new InvalidOperationException("Це локальний пристрій.");
        if(!await IsOnlineAsync(target,cancellation))
            return new(false,DeviceRouting.Label(target)+" не підключений до JARVIS Relay.");
        var (url,token)=Credentials();
        var id=Guid.NewGuid();
        using(var sent=await SendAsync(Request(HttpMethod.Post,
            new Uri(url,"/device/v1/send").ToString(),token,
            new {id=id.ToString(),origin=DeviceRouting.WireId(origin),
                target=DeviceRouting.WireId(target),command=utterance}),cancellation)) {
            // Server acknowledges queueing only, not execution.
            if(!sent.RootElement.TryGetProperty("id",out var confirmed) ||
               confirmed.GetString()!=id.ToString())
                throw new InvalidDataException("Сервер не підтвердив ID запиту.");
        }
        for(int i=0;i<24;i++) {
            await Task.Delay(1250,cancellation);
            using var receipt=await SendAsync(Request(HttpMethod.Get,
                new Uri(url,$"/device/v1/result?id={id}&origin={DeviceRouting.WireId(origin)}").ToString(),
                token),cancellation);
            if(receipt.RootElement.GetProperty("done").GetBoolean()) {
                return new(receipt.RootElement.GetProperty("ok").GetBoolean(),
                    receipt.RootElement.GetProperty("detail").GetString()??"");
            }
        }
        return new(false,"Команду доставлено до черги, але пристрій не підтвердив виконання за 30 с.");
    }

    public async Task ListenAsync(CancellationToken cancellation) {
        while(!cancellation.IsCancellationRequested) {
            try {
                var (url,token)=Credentials();
                using var received=await SendAsync(Request(HttpMethod.Get,
                    new Uri(url,"/device/v1/poll?device=computer").ToString(),token),cancellation);
                var items=received.RootElement.GetProperty("items");
                foreach(var item in items.EnumerateArray()) {
                    var command=new RemoteCommand(
                        Guid.Parse(item.GetProperty("id").GetString()!),
                        item.GetProperty("origin").GetString()??"",
                        item.GetProperty("target").GetString()??"",
                        item.GetProperty("command").GetString()??"");
                    RemoteResult result;
                    if(_completed.Contains(command.Id))result=new(true,"Команда вже виконана.");
                    else if(CommandReceived==null)result=new(false,"Windows JARVIS не приймає дистанційні команди.");
                    else {
                        try {result=await CommandReceived.Invoke(command);}
                        catch(Exception e){result=new(false,"Windows відхилив команду: "+e.Message);}
                        // A denied command is also completed; never execute it twice.
                        _completed.Add(command.Id);
                        if(_completed.Count>256)_completed.Clear();
                    }
                    try {
                        using var ack=await SendAsync(Request(HttpMethod.Post,
                            new Uri(url,"/device/v1/ack").ToString(),token,
                            new {id=command.Id.ToString(),device="computer",
                                ok=result.Ok,detail=result.Detail[..Math.Min(1400,result.Detail.Length)]}),
                            cancellation);
                    }catch(Exception error){Status?.Invoke("Не вдалося передати ACK: "+error.Message);}
                }
            }catch(OperationCanceledException) {break;}
             catch(Exception error) {Status?.Invoke("Зв'язок Windows: "+error.Message);}
            try {await Task.Delay(3000,cancellation);}
            catch(OperationCanceledException) {break;}
        }
    }
    public void Dispose()=>_http.Dispose();
}
